#include <cstddef>

class Buffer
{
public:
    Buffer() {}
    explicit Buffer(std::size_t size, int fill = 0) {}
    ~Buffer() {}
    Buffer(const Buffer& other) {}
    Buffer(Buffer&& other) noexcept {}
    Buffer& operator=(Buffer other) noexcept { return *this; }
    friend void swap(Buffer& a, Buffer& b) noexcept {}

    std::size_t size() const { return 0; }
    const int* data() const { return nullptr; }
    int& operator[](std::size_t i) { static int dummy{ 0 }; return dummy; }
    int operator[](std::size_t i) const { return 0; }
};

solution.solution.cpp:
#include <algorithm>
#include <cstddef>
#include <utility>

class Buffer
{
public:
    Buffer() = default;

    explicit Buffer(std::size_t size, int fill = 0) : items{ size ? new int[size] : nullptr }, count{ size }
    {
        std::fill(items, items + count, fill);
    }

    ~Buffer() { delete[] items; }

    Buffer(const Buffer& other) : items{ other.count ? new int[other.count] : nullptr }, count{ other.count }
    {
        std::copy(other.items, other.items + other.count, items);
    }

    Buffer(Buffer&& other) noexcept : items{ other.items }, count{ other.count }
    {
        other.items = nullptr;
        other.count = 0;
    }

    Buffer& operator=(Buffer other) noexcept
    {
        swap(*this, other);
        return *this;
    }

    friend void swap(Buffer& a, Buffer& b) noexcept
    {
        std::swap(a.items, b.items);
        std::swap(a.count, b.count);
    }

    std::size_t size() const { return count; }
    const int* data() const { return items; }
    int& operator[](std::size_t i) { return items[i]; }
    int operator[](std::size_t i) const { return items[i]; }

private:
    int* items{ nullptr };
    std::size_t count{ 0 };
};

unitTests:
#include <cstdlib>
#include <new>
#include <vector>
static int liveArrays{ 0 };
void* operator new[](std::size_t size) { ++liveArrays; if (void* p{ std::malloc(size ? size : 1) }) return p; throw std::bad_alloc{}; }
void operator delete[](void* p) noexcept { if (p) { --liveArrays; std::free(p); } }
void operator delete[](void* p, std::size_t) noexcept { if (p) { --liveArrays; std::free(p); } }

TEST("construct and destroy") {
    const int before{ liveArrays };
    {
        Buffer empty;
        CHECK_EQ(empty.size(), 0u);
        CHECK(empty.data() == nullptr);
        Buffer b{ 4, 7 };
        CHECK_EQ(b.size(), 4u);
        CHECK_EQ(b[3], 7);
        CHECK_EQ(liveArrays, before + 1);
    }
    CHECK_EQ(liveArrays, before);
}
TEST("copies are deep") {
    const int before{ liveArrays };
    {
        Buffer a{ 3, 1 };
        Buffer b{ a };
        CHECK(b.data() != a.data());
        b[0] = 99;
        CHECK_EQ(a[0], 1);
        CHECK_EQ(liveArrays, before + 2);
        Buffer c;
        c = a;
        c[1] = 50;
        CHECK_EQ(a[1], 1);
        CHECK_EQ(c.size(), 3u);
    }
    CHECK_EQ(liveArrays, before);
}
TEST("moves steal") {
    const int before{ liveArrays };
    {
        Buffer a{ 5, 2 };
        const int* original{ a.data() };
        Buffer b{ std::move(a) };
        CHECK(b.data() == original);
        CHECK(a.data() == nullptr);
        CHECK_EQ(a.size(), 0u);
        CHECK_EQ(liveArrays, before + 1);
        Buffer c{ 1 };
        c = std::move(b);
        CHECK(c.data() == original);
        CHECK_EQ(liveArrays, before + 1);
    }
    CHECK_EQ(liveArrays, before);
}
TEST("self-assignment and vectors of buffers") {
    const int before{ liveArrays };
    {
        Buffer a{ 2, 9 };
        Buffer& alias{ a };
        a = alias;
        CHECK_EQ(a.size(), 2u);
        CHECK_EQ(a[1], 9);
        std::vector<Buffer> many;
        for (int i{ 0 }; i < 20; ++i) many.emplace_back(3, i);
        CHECK_EQ(many[19][2], 19);
        CHECK_EQ(liveArrays, before + 21);
    }
    CHECK_EQ(liveArrays, before);
}

